"""ADMINS HELPER standalone browser website (safe first-stage build).
Uses existing db_backend.py. Does not replace the running Telegram Mini App.
Required env: OWNER_ID, SESSION_SECRET, WEB_OWNER_PASSWORD. Optional: WEB_OWNER_USERNAME, MINIAPP_DB, DATABASE_URL.
"""
import os, re, json, time, hmac, hashlib, secrets
from datetime import datetime, timezone
from fastapi import FastAPI, Request, HTTPException, Response
from fastapi.responses import HTMLResponse
from pydantic import BaseModel, Field
from db_backend import db, initialize_database, USING_POSTGRES
initialize_database(os.getenv("MINIAPP_DB", "miniapp.db"), os.getenv("ADMIN_PASSWORD", "legacy-disabled-no-login"))

OWNER_ID = int(os.getenv('OWNER_ID', '0') or 0)
SESSION_SECRET = os.getenv('SESSION_SECRET', '')
BRIDGE_SECRET = os.getenv('BRIDGE_SECRET', '')
OWNER_USERNAME = os.getenv('WEB_OWNER_USERNAME', 'owner').strip().lower()
OWNER_PASSWORD = os.getenv('WEB_OWNER_PASSWORD', '')
COOKIE_NAME = 'ah_session'
COOKIE_SECURE = os.getenv('COOKIE_SECURE', 'true').lower() != 'false'
if not SESSION_SECRET or len(SESSION_SECRET) < 32:
    raise RuntimeError('SESSION_SECRET kamida 32 belgili maxfiy qiymat bo‘lishi kerak')
if not OWNER_PASSWORD or len(OWNER_PASSWORD) < 12:
    raise RuntimeError('WEB_OWNER_PASSWORD kamida 12 belgidan iborat bo‘lishi kerak')
if not re.fullmatch(r'[a-z0-9_.-]{3,32}', OWNER_USERNAME):
    raise RuntimeError('WEB_OWNER_USERNAME: 3-32 ta lotin harfi, raqam, nuqta, _ yoki -')

app = FastAPI(title='ADMINS HELPER Cyber Control', docs_url=None, redoc_url=None)

SCHEMA = '''
CREATE TABLE IF NOT EXISTS web_admins (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 username TEXT NOT NULL UNIQUE,
 display_name TEXT NOT NULL,
 salt TEXT NOT NULL,
 password_hash TEXT NOT NULL,
 permissions TEXT NOT NULL,
 active INTEGER NOT NULL DEFAULT 1,
 session_version BIGINT NOT NULL DEFAULT 1,
 created_at BIGINT NOT NULL,
 updated_at BIGINT NOT NULL
);
CREATE TABLE IF NOT EXISTS web_security_settings (
 key TEXT PRIMARY KEY, value TEXT NOT NULL, updated_at BIGINT NOT NULL
);
CREATE TABLE IF NOT EXISTS web_guard_events (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 chat_id BIGINT, user_id BIGINT, username TEXT, reason TEXT NOT NULL,
 confidence TEXT NOT NULL DEFAULT 'review', status TEXT NOT NULL DEFAULT 'pending',
 created_at BIGINT NOT NULL, reviewed_by BIGINT
);
CREATE TABLE IF NOT EXISTS web_login_attempts (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, ip_hash TEXT NOT NULL, username TEXT NOT NULL, success INTEGER NOT NULL, attempted_at BIGINT NOT NULL
);
CREATE INDEX IF NOT EXISTS web_login_attempts_recent ON web_login_attempts(ip_hash, attempted_at);
'''
with db() as c:
    script = SCHEMA if USING_POSTGRES else SCHEMA.replace('BIGINT GENERATED BY DEFAULT AS IDENTITY', 'INTEGER').replace('BIGINT', 'INTEGER')
    c.executescript(script)
    row = c.execute('SELECT id FROM web_admins WHERE username=?', (OWNER_USERNAME,)).fetchone()
    if not row:
        salt = secrets.token_hex(16)
        digest = hashlib.pbkdf2_hmac('sha256', OWNER_PASSWORD.encode(), bytes.fromhex(salt), 310000).hex()
        perms = {"dashboard": True, "groups_view": True, "messages_view": True, "messages_send": True,
                 "admins_manage": True, "security_manage": True, "guard_review": True, "audit_view": True}
        c.execute('INSERT INTO web_admins(username,display_name,salt,password_hash,permissions,active,created_at,updated_at) VALUES(?,?,?,?,?,1,?,?)',
                  (OWNER_USERNAME, 'Owner', salt, digest, json.dumps(perms), int(time.time()), int(time.time())))
    owner_row = c.execute('SELECT id,permissions FROM web_admins WHERE username=?', (OWNER_USERNAME,)).fetchone()
    if owner_row:
        owner_perms = json.loads(owner_row['permissions'])
        owner_perms['admins_manage'] = True
        c.execute('UPDATE web_admins SET permissions=? WHERE id=?', (json.dumps(owner_perms), owner_row['id']))
    defaults = {
        'guard_enabled': '0', 'guard_profile_scan': '1', 'guard_channel_scan': '0',
        'guard_auto_ban': '0', 'guard_review_mode': '1', 'antiraid_enabled': '0',
        'antispam_enabled': '0', 'ai_guard_enabled': '0'
    }
    for k, v in defaults.items():
        c.execute('INSERT INTO web_security_settings(key,value,updated_at) VALUES(?,?,?) ON CONFLICT(key) DO NOTHING', (k, v, int(time.time())))

def hash_password(password: str, salt_hex: str) -> str:
    return hashlib.pbkdf2_hmac('sha256', password.encode(), bytes.fromhex(salt_hex), 310000).hex()

def make_session(admin_id: int, version: int) -> str:
    exp = int(time.time()) + 8 * 3600
    body = f'{admin_id}:{exp}:{version}'
    sig = hmac.new(SESSION_SECRET.encode(), body.encode(), hashlib.sha256).hexdigest()
    return body + ':' + sig

def current_admin(request: Request):
    token = request.cookies.get(COOKIE_NAME, '')
    try:
        admin_id_s, exp_s, version_s, sig = token.split(':', 3)
        body = ':'.join((admin_id_s, exp_s, version_s))
        expected = hmac.new(SESSION_SECRET.encode(), body.encode(), hashlib.sha256).hexdigest()
        if not hmac.compare_digest(sig, expected) or int(exp_s) < int(time.time()):
            raise ValueError()
        with db() as c:
            row = c.execute('SELECT * FROM web_admins WHERE id=? AND active=1', (int(admin_id_s),)).fetchone()
        if not row or int(row['session_version']) != int(version_s):
            raise ValueError()
        return row
    except Exception:
        raise HTTPException(401, 'Sessiya tugagan. Qayta kiring.')

def require_perm(request: Request, perm: str):
    row = current_admin(request)
    perms = json.loads(row['permissions'])
    if not perms.get(perm, False):
        raise HTTPException(403, 'Bu bo‘lim uchun ruxsat berilmagan')
    return row

def require_owner(request: Request):
    row = current_admin(request)
    if not json.loads(row['permissions']).get('admins_manage', False):
        raise HTTPException(403, 'Faqat Owner bu amalni bajaradi')
    return row

class LoginBody(BaseModel):
    username: str = Field(min_length=3, max_length=32)
    password: str = Field(min_length=1, max_length=256)

class AdminCreate(BaseModel):
    username: str = Field(min_length=3, max_length=32, pattern=r'^[a-zA-Z0-9_.-]+$')
    display_name: str = Field(min_length=1, max_length=60)
    password: str = Field(min_length=12, max_length=256)
    permissions: dict[str, bool] = {}

class AdminUpdate(BaseModel):
    display_name: str | None = Field(default=None, min_length=1, max_length=60)
    password: str | None = Field(default=None, min_length=12, max_length=256)
    permissions: dict[str, bool] | None = None
    active: bool | None = None

