@app.post('/api/auth/login')
def login(body: LoginBody, request: Request, response: Response):
    username = body.username.strip().lower()
    remote = request_ip = 'unknown'
    # Only a keyed digest of the network address is stored; raw IP addresses are not retained.
    remote = request.client.host if request.client else 'unknown'
    ip_hash = hmac.new(SESSION_SECRET.encode(), remote.encode(), hashlib.sha256).hexdigest()
    now = int(time.time())
    with db() as c:
        attempts = c.execute('SELECT COUNT(*) FROM web_login_attempts WHERE ip_hash=? AND attempted_at>? AND success=0', (ip_hash, now-900)).fetchone()[0]
        if attempts >= 8:
            raise HTTPException(429, 'Juda ko‘p urinish. 15 daqiqadan keyin qayta urinib ko‘ring.')
        row = c.execute('SELECT * FROM web_admins WHERE username=? AND active=1', (username,)).fetchone()
        valid = bool(row and hmac.compare_digest(hash_password(body.password, row['salt']), row['password_hash']))
        c.execute('INSERT INTO web_login_attempts(ip_hash,username,success,attempted_at) VALUES(?,?,?,?)', (ip_hash, username[:32], int(valid), now))
        c.execute('DELETE FROM web_login_attempts WHERE attempted_at<?', (now-86400,))
    if not valid:
        raise HTTPException(401, 'Login yoki parol noto‘g‘ri')
    response.set_cookie(COOKIE_NAME, make_session(int(row['id']), int(row['session_version'])),
                        httponly=True, secure=COOKIE_SECURE, samesite='strict', max_age=28800, path='/')
    return {'ok': True, 'display_name': row['display_name']}

@app.post('/api/auth/logout')
def logout(response: Response):
    response.delete_cookie(COOKIE_NAME, path='/')
    return {'ok': True}

@app.get('/api/me')
def me(request: Request):
    row = current_admin(request)
    return {'id': row['id'], 'username': row['username'], 'display_name': row['display_name'],
            'permissions': json.loads(row['permissions'])}

@app.get('/api/dashboard')
def dashboard(request: Request):
    row = require_perm(request, 'dashboard')
    with db() as c:
        groups = c.execute('SELECT COUNT(*) FROM groups').fetchone()[0]
        messages = c.execute('SELECT COUNT(*) FROM messages').fetchone()[0]
        admins = c.execute('SELECT COUNT(*) FROM web_admins WHERE active=1').fetchone()[0]
        pending = c.execute("SELECT COUNT(*) FROM web_guard_events WHERE status='pending'").fetchone()[0]
    return {'groups': groups, 'messages': messages, 'admins': admins, 'guard_pending': pending,
            'role': 'Owner' if json.loads(row['permissions']).get('admins_manage') else 'Admin'}

@app.get('/api/admins')
def list_admins(request: Request):
    require_owner(request)
    with db() as c:
        rows = c.execute('SELECT id,username,display_name,permissions,active,created_at FROM web_admins ORDER BY id').fetchall()
    return [{'id': r['id'], 'username': r['username'], 'display_name': r['display_name'],
             'permissions': json.loads(r['permissions']), 'active': bool(r['active']), 'created_at': r['created_at']} for r in rows]

@app.post('/api/admins')
def create_admin(body: AdminCreate, request: Request):
    owner = require_owner(request)
    username = body.username.strip().lower()
    if not re.fullmatch(r'[a-z0-9_.-]{3,32}', username):
        raise HTTPException(400, 'Login formati noto‘g‘ri')
    allowed = {'dashboard','groups_view','messages_view','messages_send','security_manage','guard_review','audit_view'}
    perms = {k: bool(v) for k, v in body.permissions.items() if k in allowed}
    perms['admins_manage'] = False
    salt = secrets.token_hex(16)
    digest = hash_password(body.password, salt)
    now = int(time.time())
    try:
        with db() as c:
            cur = c.execute('INSERT INTO web_admins(username,display_name,salt,password_hash,permissions,active,created_at,updated_at) VALUES(?,?,?,?,?,1,?,?) RETURNING id',
                            (username, body.display_name.strip(), salt, digest, json.dumps(perms), now, now))
            new_id = cur.fetchone()[0]
    except Exception:
        raise HTTPException(409, 'Bu login band yoki admin yaratilmadi')
    return {'ok': True, 'id': new_id, 'username': username}

@app.patch('/api/admins/{admin_id}')
def update_admin(admin_id: int, body: AdminUpdate, request: Request):
    require_owner(request)
    with db() as c:
        row = c.execute('SELECT * FROM web_admins WHERE id=?', (admin_id,)).fetchone()
        if not row: raise HTTPException(404, 'Admin topilmadi')
        if row['username'] == OWNER_USERNAME and body.active is False:
            raise HTTPException(400, 'Asosiy Owner hisobini o‘chirib bo‘lmaydi')
        display = body.display_name.strip() if body.display_name is not None else row['display_name']
        perms = json.loads(row['permissions'])
        if body.permissions is not None:
            allowed = {'dashboard','groups_view','messages_view','messages_send','security_manage','guard_review','audit_view'}
            perms = {k: bool(v) for k, v in body.permissions.items() if k in allowed}
            if row['username'] == OWNER_USERNAME: perms['admins_manage'] = True
        salt, digest = row['salt'], row['password_hash']
        if body.password:
            salt = secrets.token_hex(16); digest = hash_password(body.password, salt)
        active = int(body.active) if body.active is not None else int(row['active'])
        version = int(row['session_version']) + (1 if body.password is not None or body.active is not None and not body.active else 0)
        c.execute('UPDATE web_admins SET display_name=?,salt=?,password_hash=?,permissions=?,active=?,session_version=?,updated_at=? WHERE id=?',
                  (display,salt,digest,json.dumps(perms),active,version,int(time.time()),admin_id))
    return {'ok': True}

@app.delete('/api/admins/{admin_id}')
def delete_admin(admin_id: int, request: Request):
    require_owner(request)
    with db() as c:
        row = c.execute('SELECT username FROM web_admins WHERE id=?', (admin_id,)).fetchone()
        if not row: raise HTTPException(404, 'Admin topilmadi')
        if row['username'] == OWNER_USERNAME: raise HTTPException(400, 'Owner hisobini o‘chirib bo‘lmaydi')
        c.execute('DELETE FROM web_admins WHERE id=?', (admin_id,))
    return {'ok': True}

@app.get('/api/security/settings')
def security_settings(request: Request):
    require_perm(request, 'security_manage')
    with db() as c:
        rows = c.execute('SELECT key,value FROM web_security_settings ORDER BY key').fetchall()
    return {r['key']: r['value'] for r in rows}

@app.put('/api/security/settings')
def update_security_settings(data: dict, request: Request):
    require_perm(request, 'security_manage')
    allowed = {'guard_enabled','guard_profile_scan','guard_channel_scan','guard_auto_ban','guard_review_mode',
               'antiraid_enabled','antispam_enabled','ai_guard_enabled'}
    with db() as c:
        for k, v in data.items():
            if k in allowed:
                c.execute('INSERT INTO web_security_settings(key,value,updated_at) VALUES(?,?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value,updated_at=excluded.updated_at',
                          (k, '1' if str(v).lower() in ('1','true','on') else '0', int(time.time())))
    return {'ok': True}

@app.get('/api/guard/events')
def guard_events(request: Request):
    require_perm(request, 'guard_review')
    with db() as c:
        rows = c.execute('SELECT * FROM web_guard_events ORDER BY created_at DESC LIMIT 100').fetchall()
    return [dict(r) for r in rows]

@app.post('/api/guard/events/{event_id}/review')
def review_guard_event(event_id: int, data: dict, request: Request):
    reviewer = require_perm(request, 'guard_review')
    status = data.get('status')
    if status not in ('approved','rejected','needs_review'):
        raise HTTPException(400, 'Holat noto‘g‘ri')
    with db() as c:
        found = c.execute("SELECT id FROM web_guard_events WHERE id=? AND status='pending'", (event_id,)).fetchone()
        if not found: raise HTTPException(404, 'Kutilayotgan tekshiruv topilmadi')
        c.execute("UPDATE web_guard_events SET status=?,reviewed_by=? WHERE id=?", (status,int(reviewer['id']),event_id))
    return {'ok': True}

